def encode_caesar(text, k):
    """Shift each alphabetic character k positions forward, wrapping within its case."""
    out = []
    for ch in text:
        if 'a' <= ch <= 'z':
            out.append(chr((ord(ch) - 97 + k) % 26 + 97))
