def expand_string_runs(s):
    """Run-length decode a string: 'a3b2c1' -> 'aaabbc'."""
    out = []
    i = 0
    while i < len(s):
        ch = s[i]
        i += 1
        num = ''
        while i < len(s) and s[i].isdigit():
            num += s[i]
            i += 1
        out.append(ch * int(num))
    return ''.join(out)

