def compress_string_runs(s):
    """Run-length encode a string: 'aaabbc' -> 'a3b2c1'."""
    if not s:
        return ''
    out = []
    run = 1
    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            run += 1
        else:
            out.append(s[i - 1] + str(run))
