# variance_of :: [1.5, 2.5]
def variance_of(xs):
    """Population variance of a list of numbers."""
    m = sum(xs) / len(xs)
    return sum((x - m) ** 2 for x in xs) / len(xs)

if __name__ == "__main__":
    print(variance_of([1.5, 2.5]))

